import json
from http.server import BaseHTTPRequestHandler, HTTPServer
from urllib.parse import urlparse, parse_qs

WEATHER = {"delhi": {"temp_c": 31, "sky": "haze"},
           "london": {"temp_c": 14, "sky": "cloudy"},
           "dubai": {"temp_c": 38, "sky": "sunny"}}

class WeatherAPI(BaseHTTPRequestHandler):
    def do_GET(self):
        url = urlparse(self.path)
        city = parse_qs(url.query).get("city", [""])[0].lower()
        if url.path == "/weather" and city in WEATHER:
            status, body = 200, {"city": city, **WEATHER[city]}
        else:
            status, body = 404, {"error": f"no weather data for '{city}'"}
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(json.dumps(body).encode())

    def log_message(self, *args):     # keep the terminal quiet
        pass

import json
from urllib.request import urlopen
from urllib.error import HTTPError

def ask(url):
    try:
        with urlopen(url) as response:
            return response.status, json.loads(response.read())
    except HTTPError as error:
        return error.code, json.loads(error.read())

for city in ["Delhi", "London", "Atlantis"]:
    status, data = ask(f"http://localhost:8765/weather?city={city}")
    print(status, data)

# the program only needs the parts it cares about
status, data = ask("http://localhost:8765/weather?city=dubai")
print(f"It is {data['temp_c']} degrees and {data['sky']} in {data['city'].title()}.")

